-- Align every owned serial/identity sequence with the imported maximum value.
DO $$
DECLARE
    r record;
    max_id bigint;
BEGIN
    FOR r IN
        SELECT n.nspname AS schema_name, c.relname AS table_name, a.attname AS column_name,
               pg_catalog.pg_get_serial_sequence(pg_catalog.format('%I.%I', n.nspname, c.relname), a.attname) AS sequence_name
        FROM pg_catalog.pg_class c
        JOIN pg_catalog.pg_namespace n ON n.oid = c.relnamespace
        JOIN pg_catalog.pg_attribute a ON a.attrelid = c.oid
        WHERE n.nspname = 'public' AND c.relkind IN ('r', 'p')
          AND a.attnum > 0 AND NOT a.attisdropped
    LOOP
        IF r.sequence_name IS NOT NULL THEN
            EXECUTE pg_catalog.format('SELECT max(%I)::bigint FROM %I.%I', r.column_name, r.schema_name, r.table_name) INTO max_id;
            IF max_id IS NULL THEN
                PERFORM pg_catalog.setval(r.sequence_name::regclass, 1, false);
            ELSE
                PERFORM pg_catalog.setval(r.sequence_name::regclass, max_id, true);
            END IF;
        END IF;
    END LOOP;
END $$;

